"""Local launch-readiness view; does not enable indexing."""
import news,seo,editorial

def page():
 articles=news.articles();published=[a for a in articles if a.get('reviewStatus')=='approved' and a.get('publicationStatus')=='published' and a.get('webPublishedAt')]
 events,status=news.app_content.get()
 checks=[('Klaar','Eigen URL per artikel','Elk bericht heeft een vaste URL. Beeldkeuze verandert de canonical niet.'),('Klaar','Lokale zoekintentie','26 gemeenten met agenda, vandaag, morgen en dit weekend. Gemeente en onderwerp hebben aparte routes.'),('Klaar','Doorleesstructuur','Gemeente, onderwerp, dossier en gerelateerde artikelen linken naar elkaar.'),('Klaar','Gestructureerde gegevens','NewsArticle, CollectionPage, ItemList, BreadcrumbList en uitgever; Event alleen bij complete activiteitgegevens.'),('Klaar','Sociale deelkaarten','Titel, omschrijving, canonical en beeld voor Open Graph en Twitter Cards.'),('Klaar','Publicatie en brondatum gescheiden','Alleen echte PITO-publicatiedata mogen in datePublished en Google News-sitemaps staan.'),('Nog nodig','Publieke lancering','De lokale preview blijft noindex. Stel productie-origin, publicatierechten en indexeerbare pagina’s in de bestaande website in.'),('Nog nodig','Strapi-activiteiten','De agenda-aansluiting is '+('beschikbaar' if status=='connected' else 'nog niet actief')+'. Lege agenda’s mogen niet als gevulde zoeklandingspagina’s worden gepresenteerd.'),('Nog nodig','Redactie en auteurs','Wijs verantwoordelijke redacteurs toe, maak publieke auteursprofielen en publiceer het correctieproces.'),('Nog nodig','Search Console en monitoring','Verifieer pito.app, dien sitemaps in en meet indexering, zoekvragen en Core Web Vitals op de echte hosting.')]
 cards=''.join('<article class="seo-check"><span class="eyebrow '+('pending' if state=='Nog nodig' else '')+'">'+state+'</span><h3>'+title+'</h3><p>'+news.e(text)+'</p></article>' for state,title,text in checks)
 paths=[('Nieuws uit Woerden','/nieuws/utrecht/woerden'),('Wat is er vandaag te doen in Woerden?',seo.agenda_path('woerden','vandaag')),('Agenda Woerden',seo.agenda_path('woerden')),('Dit weekend in Rhenen',seo.agenda_path('rhenen','dit-weekend')),('Politiek en bestuur in Woerden',seo.topic_path('woerden','Bestuur')),('Woningbouw in Utrecht','/nieuws/dossiers/wonen-en-bouwen')]
 examples=''.join('<tr><th scope="row">'+news.e(label)+'</th><td><a href="'+path+'">'+path+'</a></td></tr>' for label,path in paths)
 body=editorial.breadcrumb([('PITO','/'),('Redactie','/nieuws/redactie'),('SEO-controle','/nieuws/seo-controle')])+'<section class="section seo-review"><p class="eyebrow">VINDBAAR VANUIT JOUW GEMEENTE</p><h1>Een duidelijke route.<br>Voor mensen én zoekmachines.</h1><p class="standfirst">SEO zit in de opbouw van de site: één bruikbare pagina per zoekvraag, echte inhoud en logische verbindingen.</p><div class="notice">Deze ontwikkelomgeving is bewust niet indexeerbaar. '+str(len(published))+' artikelen hebben een openbare publicatiestatus. Er wordt geen Google-positie of indexering beloofd.</div><div class="seo-checks">'+cards+'</div><h2>Van zoekvraag naar pagina</h2><div class="table-scroll"><table><thead><tr><th>Zoekvraag</th><th>Vaste bestemming</th></tr></thead><tbody>'+examples+'</tbody></table></div><h2>Sitemaps</h2><p><a href="/nieuws/sitemap.xml">Algemene nieuwssitemap</a> · <a href="/nieuws/news-sitemap.xml">Google News-sitemap</a></p><p>Concepten blijven buiten de sitemaps. Google News bevat uitsluitend eigen openbare publicaties van de laatste twee dagen, maximaal 1.000 per bestand. Paginering houdt een eigen canonical; zoek- en filtercombinaties horen niet allemaal in de sitemap.</p><h2>Onderbouwd met officiële documentatie</h2><ul><li><a href="https://developers.google.com/search/docs/appearance/structured-data/article">Google: artikelgegevens</a></li><li><a href="https://developers.google.com/search/docs/crawling-indexing/sitemaps/news-sitemap">Google: nieuws-sitemaps</a></li><li><a href="https://developers.google.com/search/docs/appearance/structured-data/event">Google: activiteiten</a></li><li><a href="https://developers.google.com/search/docs/crawling-indexing/consolidate-duplicate-urls">Google: dubbele URL’s en canonicals</a></li></ul></section>'
 return news.layout('SEO en publicatiegereedheid',body,'/nieuws/seo-controle')
